        s5_p1: "Üst katmanı çevirerek olabildiğince çok kenarın yan rengini altındaki merkezle eşleştir; en az iki kenar eşleşir.",
        s5_p2: "Komşu iki kenar eşleşiyorsa küpü elinde döndür: eşleşenler arkada ve sağda olsun. Sonra algoritmayı yap ve en sonda üst katmanı bir kez çevir (U):",
