        s0_p1: "A cube has three kinds of pieces: centers (the middle of each face, 6 of them), edges (2 colors, 12 of them) and corners (3 colors, 8 of them). Centers never move relative to each other; a face's color is the color of its center.",
        s0_p2: "In this guide, always hold the cube with the yellow center on top and the green center in front. That puts white on the bottom, orange on the right, red on the left and blue at the back.",
        not_title: "Notation: reading the moves",
        not_p1: "Each letter means turning a face a quarter turn (90°) clockwise, as if you were looking straight at that face. An apostrophe (') means the opposite direction, and 2 means a half turn (twice).",
        not_p2: "Example: R2 = R R. Do algorithms from left to right, one letter at a time.",
        mv_R: "Right",
        mv_L: "Left",
        mv_U: "Up",
        mv_D: "Down",
        mv_F: "Front",
        mv_B: "Back",
        mv_prime: "inverse",
        s1_title: "Step 1 — White cross",
        s1_p1: "First make a daisy: bring the four white edges around the yellow center with white facing up. There's no algorithm here; turn the edges up into the free spots around the yellow center.",
        s1_p2: "Then for each white edge: turn the top layer (U) until the edge's side color matches the center below it, then turn that face twice (e.g. F2). After all four, there's a white cross on the bottom with the side colors matching the centers.",
        s1_c1: "Daisy: white edges around the yellow center",
        s1_c2: "Result: white cross on the bottom (seen from below)",
        s2_title: "Step 2 — White corners",
        s2_p1: "Find a white corner in the top layer. Turn the top layer to bring it right above where it belongs, to the front-right-top: its other two colors must match the two centers below it.",
        s2_p2: "Then repeat this move until the corner drops into place:",
        s2_p3: "1 time if white faces right, 3 times if it faces up, 5 times if it faces front. If a corner is in the bottom but in the wrong spot or twisted, bring it to front-right-bottom and do R U R' U' once to lift it up.",
        s2_c1: "White on the right: 1 time",
        s2_c3: "White on top: 3 times",
        s2_c5: "White in front: 5 times",
        s3_title: "Step 3 — Middle layer",
        s3_p1: "With yellow still on top, find an edge in the top layer that has no yellow. Turn the top layer to match the edge's front color with the front center. The edge goes toward the side whose center matches its top color.",
        s3_right: "If it goes to the right:",
        s3_left: "If it goes to the left:",
        s3_p2: "If an edge in the middle layer is in the wrong spot or flipped, bring it to front-right and do the right algorithm once; the edge comes up to the top.",
        s3_c1: "Goes right (orange on top)",
        s3_c2: "Goes left (red on top)",
        s4_title: "Step 4 — Yellow cross",
        s4_p1: "Look at the yellow edges on top (ignore the corners for now). You'll see one of four shapes; the same algorithm works for all of them:",
        s4_dot: "Dot: do the algorithm once and you get an L.",
        s4_L: "L: put the L at the back-left (yellow at the back and left), do the algorithm; you get a line.",
        s4_line: "Line: hold it horizontally (left to right), do the algorithm; you get a cross.",
        s4_cross: "Cross: this step is done!",
        s5_title: "Step 5 — Match the yellow edges",
        s5_p1: "Turn the top layer so that as many edges as possible match the center below them; at least two will match.",
        s5_p2: "If two neighboring edges match, turn the whole cube so the matching ones are at the back and right. Do the algorithm, then turn the top layer once more (U):",
        s5_p3: "If two opposite edges match, do the algorithm once from any side; you'll get the neighboring case.",
        s5_c1: "Before: back and right match",
        s5_c2: "After: all four edges match",
        s6_title: "Step 6 — Place the yellow corners",
        s6_p1: "A corner is in the right spot if its three colors are the colors of the three centers around it. Its orientation (where the yellow faces) doesn't matter yet.",
        s6_p2: "Turn the whole cube so a correctly placed corner is at front-right-top, and do the algorithm until the others fall into place (1 or 2 times):",
        s6_p3: "If no corner is in the right spot, do the algorithm once; one corner will land in place.",
        s6_c1: "Before: only the front-right corner is in place",
        s6_c2: "After 2 times: all in place",
        s7_title: "Step 7 — Twist the yellow corners",
        s7_p1: "Keep yellow on top. Bring a corner whose yellow isn't facing up to front-right-top and repeat this move until yellow faces up (2 or 4 times):",
        s7_warn: "The bottom layers will look scrambled while you do this. Don't panic, keep going!",
        s7_p2: "When that corner is done, don't turn the whole cube: only turn the top layer (U) to bring the next corner to front-right-top and repeat. Once all corners are done the bottom layers fix themselves; finally turn the top layer to finish the cube.",
        s7_c1: "Yellow faces right",
        s7_c2: "After 2 times: yellow on top",
        done_title: "Congratulations, you solved the cube! 🎉",
