        s1_p2: "Затем для каждого белого ребра: поворачивай верхний слой (U), пока боковой цвет ребра не совпадёт с центром под ним, и поверни эту грань дважды (например, F2). После всех четырёх внизу будет белый крест, совпадающий с центрами.",
