        s7_p2: "Когда угол готов, не поворачивай весь кубик: поверни только верхний слой (U), чтобы следующий угол оказался спереди-справа-сверху, и повтори. Когда все углы готовы, нижние слои соберутся сами; в конце поверни верхний слой, чтобы закончить.",
        s7_c1: "Жёлтый смотрит вправо",
        s7_c2: "После 2 раз: жёлтый сверху",
