    de: {
        back_btn: "← Zurück",
        badge: "ANFÄNGER-ANLEITUNG",
        title: "So löst du einen 3x3 Zauberwürfel",
        hero_p: "Die Ebenen-Methode Schritt für Schritt für absolute Anfänger: 7 Schritte, nur 6 Algorithmen. Jeden Schritt haben wir in einer Würfel-Simulation an Tausenden verdrehten Würfeln getestet.",
        toc_title: "Schritte",
        s0_title: "Bevor du startest: lerne den Würfel kennen",
        s0_p1: "Ein Würfel hat drei Arten von Teilen: Mittelteile (die Mitte jeder Seite, 6 Stück), Kanten (2 Farben, 12 Stück) und Ecken (3 Farben, 8 Stück). Die Mittelteile bewegen sich nie relativ zueinander; die Farbe einer Seite ist die Farbe ihres Mittelteils.",
        s0_p2: "Halte den Würfel in dieser Anleitung immer mit dem gelben Mittelteil oben und dem grünen vorne. Dann ist Weiß unten, Orange rechts, Rot links und Blau hinten.",
        not_title: "Notation: Züge lesen",
        not_p1: "Jeder Buchstabe bedeutet, eine Seite eine Vierteldrehung (90°) im Uhrzeigersinn zu drehen, so als würdest du direkt auf diese Seite schauen. Ein Apostroph (') bedeutet die Gegenrichtung, eine 2 eine halbe Drehung (zweimal).",
        not_p2: "Beispiel: R2 = R R. Führe Algorithmen von links nach rechts aus, Buchstabe für Buchstabe.",
        mv_R: "Rechts",
        mv_L: "Links",
        mv_U: "Oben",
        mv_D: "Unten",
        mv_F: "Vorne",
        mv_B: "Hinten",
        mv_prime: "gegen",
        s1_title: "Schritt 1 — Weißes Kreuz",
        s1_p1: "Mach zuerst ein Gänseblümchen: Bringe die vier weißen Kanten mit Weiß nach oben um das gelbe Mittelteil. Hier gibt es keinen Algorithmus; drehe die Kanten nach oben auf die freien Plätze um das gelbe Mittelteil.",
        s1_p2: "Dann für jede weiße Kante: Drehe die obere Ebene (U), bis die Seitenfarbe der Kante zum Mittelteil darunter passt, und drehe diese Seite zweimal (z. B. F2). Nach allen vier ist unten ein weißes Kreuz, passend zu den Mittelteilen.",
        s1_c1: "Gänseblümchen: weiße Kanten um das gelbe Mittelteil",
        s1_c2: "Ergebnis: weißes Kreuz unten (von unten gesehen)",
        s2_title: "Schritt 2 — Weiße Ecken",
        s2_p1: "Finde eine weiße Ecke in der oberen Ebene. Drehe die obere Ebene, bis sie genau über ihrem Platz ist, vorne-rechts-oben: Ihre anderen beiden Farben müssen zu den zwei Mittelteilen darunter passen.",
        s2_p2: "Wiederhole dann diesen Zug, bis die Ecke an ihrem Platz ist:",
        s2_p3: "1-mal, wenn Weiß nach rechts zeigt, 3-mal nach oben, 5-mal nach vorne. Ist eine Ecke unten, aber am falschen Platz oder verdreht, bringe sie nach vorne-rechts-unten und mache einmal R U R' U', um sie nach oben zu holen.",
        s2_c1: "Weiß rechts: 1-mal",
        s2_c3: "Weiß oben: 3-mal",
        s2_c5: "Weiß vorne: 5-mal",
        s3_title: "Schritt 3 — Mittlere Ebene",
        s3_p1: "Gelb bleibt oben. Finde in der oberen Ebene eine Kante ohne Gelb. Drehe die obere Ebene, bis ihre vordere Farbe zum vorderen Mittelteil passt. Die Kante gehört zu der Seite, deren Mittelteil die Farbe ihrer Oberseite hat.",
        s3_right: "Wenn sie nach rechts gehört:",
        s3_left: "Wenn sie nach links gehört:",
        s3_p2: "Steckt eine Kante falsch oder gekippt in der mittleren Ebene, bringe sie nach vorne-rechts und mache einmal den rechten Algorithmus; die Kante kommt nach oben.",
        s3_c1: "Gehört nach rechts (oben orange)",
        s3_c2: "Gehört nach links (oben rot)",
        s4_title: "Schritt 4 — Gelbes Kreuz",
        s4_p1: "Schau auf die gelben Kanten oben (die Ecken sind erst mal egal). Du siehst eine von vier Formen; für alle gilt derselbe Algorithmus:",
        s4_dot: "Punkt: einmal den Algorithmus, dann entsteht ein L.",
        s4_L: "L: das L nach hinten-links (Gelb hinten und links), Algorithmus ausführen; es entsteht eine Linie.",
        s4_line: "Linie: waagerecht halten (von links nach rechts), Algorithmus ausführen; es entsteht das Kreuz.",
        s4_cross: "Kreuz: Schritt erledigt!",
        s5_title: "Schritt 5 — Gelbe Kanten anpassen",
        s5_p1: "Drehe die obere Ebene so, dass möglichst viele Kanten zum Mittelteil darunter passen; mindestens zwei passen.",
        s5_p2: "Passen zwei benachbarte Kanten, drehe den ganzen Würfel, sodass sie hinten und rechts sind. Mache den Algorithmus und drehe danach die obere Ebene noch einmal (U):",
        s5_p3: "Passen zwei gegenüberliegende Kanten, mache den Algorithmus einmal von einer beliebigen Seite; dann hast du den benachbarten Fall.",
        s5_c1: "Vorher: hinten und rechts passen",
        s5_c2: "Nachher: alle vier passen",
        s6_title: "Schritt 6 — Gelbe Ecken platzieren",
        s6_p1: "Eine Ecke sitzt richtig, wenn ihre drei Farben die der drei Mittelteile um sie herum sind. Ihre Ausrichtung (wohin Gelb zeigt) ist noch egal.",
        s6_p2: "Drehe den ganzen Würfel, sodass eine richtig sitzende Ecke vorne-rechts-oben ist, und mache den Algorithmus, bis die anderen an ihrem Platz sind (1- oder 2-mal):",
        s6_p3: "Sitzt keine Ecke richtig, mache den Algorithmus einmal; dann landet eine Ecke an ihrem Platz.",
        s6_c1: "Vorher: nur die Ecke vorne rechts sitzt",
        s6_c2: "Nach 2-mal: alle sitzen",
        s7_title: "Schritt 7 — Gelbe Ecken drehen",
        s7_p1: "Gelb bleibt oben. Bringe eine Ecke, deren Gelb nicht nach oben zeigt, nach vorne-rechts-oben und wiederhole diesen Zug, bis Gelb oben ist (2- oder 4-mal):",
        s7_warn: "Die unteren Ebenen sehen dabei verdreht aus. Keine Panik, weitermachen!",
        s7_p2: "Ist die Ecke fertig, drehe nicht den ganzen Würfel: Drehe nur die obere Ebene (U), um die nächste Ecke nach vorne-rechts-oben zu bringen, und wiederhole. Sind alle Ecken fertig, ordnen sich die unteren Ebenen von selbst; drehe zum Schluss die obere Ebene, um den Würfel fertigzustellen.",
        s7_c1: "Gelb zeigt nach rechts",
        s7_c2: "Nach 2-mal: Gelb oben",
        done_title: "Glückwunsch, du hast den Würfel gelöst! 🎉",
        done_p: "Löse ihn noch ein paar Mal, bis es flüssig läuft. Willst du schneller werden? Die nächsten Schritte:",
        next_trainer: "Algorithmen-Trainer",
        next_algos: "OLL- und PLL-Algorithmen",
        next_video: "3x3-Videoanleitungen",
        next_coach: "Einzel-Coaching buchen"
    },
