        hero_p: "طريقة الطبقات خطوة بخطوة للمبتدئين تمامًا: 7 خطوات و6 خوارزميات فقط. اختبرنا كل خطوة على آلاف المكعبات المخلوطة في محاكاة للمكعب.",
        toc_title: "الخطوات",
        s0_title: "قبل البدء: تعرّف على المكعب",
        s0_p1: "في المكعب ثلاثة أنواع من القطع: المراكز (منتصف كل وجه، 6 قطع)، والحواف (لونان، 12 قطعة)، والزوايا (3 ألوان، 8 قطع). المراكز لا تتحرك أبدًا بالنسبة لبعضها؛ ولون الوجه هو لون مركزه.",
        s0_p2: "في هذا الدليل أمسك المكعب دائمًا والمركز الأصفر للأعلى والأخضر للأمام. عندها يكون الأبيض في الأسفل، والبرتقالي يمينًا، والأحمر يسارًا، والأزرق في الخلف.",
        not_title: "الترميز: قراءة الحركات",
        not_p1: "كل حرف يعني تدوير وجه ربع دورة (90°) مع عقارب الساعة، كأنك تنظر إلى ذلك الوجه مباشرة. الفاصلة العليا (') تعني الاتجاه المعاكس، و2 تعني نصف دورة (مرتين).",
        not_p2: "مثال: R2 = R R. نفّذ الخوارزميات من اليسار إلى اليمين، حرفًا حرفًا.",
        mv_R: "يمين",
        mv_L: "يسار",
        mv_U: "أعلى",
        mv_D: "أسفل",
