        s5_p2: "إذا تطابقت حافتان متجاورتان، دوّر المكعب كله لتكونا في الخلف واليمين. نفّذ الخوارزمية ثم دوّر الطبقة العليا مرة أخرى (U):",
        s5_p3: "إذا تطابقت حافتان متقابلتان، نفّذ الخوارزمية مرة من أي جهة؛ فتحصل على حالة الحافتين المتجاورتين.",
