        s6_p1: "تكون الزاوية في مكانها الصحيح إذا كانت ألوانها الثلاثة هي ألوان المراكز الثلاثة حولها. اتجاهها (أين يتجه الأصفر) لا يهم بعد.",
        s6_p2: "دوّر المكعب كله لتكون زاوية صحيحة المكان في الأمام-يمين-أعلى، ونفّذ الخوارزمية حتى تستقر البقية (مرة أو مرتين):",
        s6_p3: "إذا لم تكن أي زاوية في مكانها، نفّذ الخوارزمية مرة؛ فتستقر زاوية واحدة.",
