                intro: "Les questions les plus posées sur le site, l'entraîneur d'algorithmes, l'installation en application et le coaching.",
                sec_general: "Général",
                sec_tools: "Entraîneur et application",
                sec_coach: "Coaching",
                q1: "Qu'est-ce que Rubik Academy ?",
                a1: "Un site d'apprentissage pour ceux qui veulent apprendre à résoudre le Rubik's Cube et devenir plus rapides : guide débutant, cours vidéo, listes d'algorithmes, entraîneur d'algorithmes et coaching individuel au même endroit.",
                q2: "Les contenus sont-ils payants ?",
                a2: "Non. Le guide débutant, les vidéos, toutes les pages d'algorithmes, l'entraîneur et les fiches à imprimer sont gratuits. Seules les séances de coaching individuel sont payantes.",
                q3: "Je ne sais pas du tout résoudre le cube. Par où commencer ?",
                a3: "Commence par le guide débutant 3x3. Apprends d'abord la notation, puis suis les 7 étapes dans l'ordre ; il suffit de mémoriser 6 algorithmes au total.",
                q4: "Quels algorithmes apprendre après la méthode débutant ?",
                a4: "Pour le 3x3, l'ordre habituel est d'abord PLL, puis OLL. Une fois maîtrisés, tu peux passer aux sets avancés comme COLL et Winter Variation. Sur 2x2, commence par Ortega OLL et PBL, puis passe à CLL et EG.",
                q5: "Que signifient les lettres comme R, U' et M2 ?",
                a5: "C'est la notation du cube : chaque lettre indique la rotation d'une face. Une lettre seule est un quart de tour horaire, l'apostrophe (') le sens inverse et 2 un demi-tour. La section notation du guide débutant les explique toutes en images.",
                q6: "Comment fonctionne l'entraîneur d'algorithmes ?",
                a6: "Tu choisis un set et les cas à travailler. L'entraîneur te donne un mélange ; tu l'appliques sur un cube résolu puis tu exécutes l'algorithme chronométré. Les cas marqués « Difficile » reviennent plus souvent. Sans cube, le mode carte te permet de t'entraîner à te rappeler l'algorithme.",
                q7: "Puis-je connecter un cube connecté (Bluetooth) ?",
                a7: "Oui. Les cubes connectés GAN (ex. GAN 12 ui, série GAN 356 i) se connectent à l'entraîneur ; le chrono démarre avec tes mouvements et s'arrête quand le cas est résolu. Il faut Chrome ou Edge sur Android ou sur ordinateur. Les navigateurs sur iPhone et iPad ne prennent pas en charge le Bluetooth.",
                q8: "Où sont enregistrés ma progression et mes statistiques ?",
                a8: "Tes marques « J'apprends / Je connais », les statistiques de l'entraîneur et le graphique de progression sont enregistrés dans le navigateur que tu utilises. Aucun compte n'est nécessaire, mais ils n'apparaissent pas sur un autre appareil. Effacer les données du navigateur les supprime aussi.",
                q9: "Puis-je installer le site sur mon téléphone comme une application ?",
                a9: "Oui. Sur Android, choisis « Installer l'application » ou « Ajouter à l'écran d'accueil » dans le menu de Chrome. Sur iPhone, touche le bouton Partager dans Safari puis « Sur l'écran d'accueil ». Le site s'ouvre alors comme une application.",
                q10: "Fonctionne-t-il sans internet ?",
                a10: "Après avoir ouvert le site une fois avec internet, les pages d'algorithmes, l'entraîneur et le guide débutant s'ouvrent aussi hors ligne. Les vidéos nécessitent internet.",
                q11: "Comment imprimer les algorithmes ?",
                a11: "Des fiches A4 d'une page sont prêtes pour OLL, PLL et CLL. Sur la page d'impression, choisis un set et appuie sur « Imprimer / PDF » ; choisis « Enregistrer au format PDF » pour obtenir un fichier PDF.",
                q12: "Pour quels puzzles le coaching est-il proposé ?",
                a12: "Des séances individuelles sont proposées pour le 2x2, le 3x3, le 3x3 à une main, le Skewb et le Megaminx. Les coachs et les prix actuels sont sur la page Coaching.",
                q13: "Comment acheter une séance de coaching ?",
                a13: "Sur la page Coaching, appuie sur « Acheter » à côté du puzzle voulu. Le paiement est effectué en toute sécurité via Shopier.",
                q14: "Comment l'horaire de la séance est-il fixé ?",
                a14: "Après le paiement, nous fixons l'horaire de la séance ensemble.",
                q15: "Comment vous contacter pour mes questions ?",
