                guide_h: "📘 Rehber: Old Pochmann ile göz bağlı çözüm",
                g_intro: "Göz bağlı çözümde küpü önce inceleyip ezberlersin, sonra gözlerini kapatıp hiç bakmadan çözersin. Old Pochmann yönteminde her seferinde tek bir parça yerine gider. Bunun için iki algoritma (T-perm ve değiştirilmiş Y-perm) ile kısa kurulum hamleleri yeter.",
