                fig_edges: "Kenar harfleri",
                fig_corners: "Köşe harfleri",
                fig_note: "Koyu etiket: tampon (buffer). Tampon parçasının diğer etiketleri hedef olamaz.",
                g_memo_h: "3. Ezberleme (iz sürme)",
                g_memo_p: "Tampondaki etikete bak: o etiket hangi yere aitse o yerin harfini yaz. Sonra o yerdeki etikete bak ve aynı şekilde devam et. Tampon parçası yeniden tampona gelirse (döngü kapanırsa) henüz yerinde olmayan herhangi bir parçanın harfini yaz ve oradan sürdür. Yerinde ama ters dönmüş parçalar da böyle iki harfle çözülür.",
                g_memo_tip: "İpucu: harfleri ikişer ikişer kelimeye çevir (ör. KA → kalem, BE → bebek). Kenarları kelimelerle, köşeleri ses olarak tekrarlayarak ezberlemek kolaydır.",
                g_edges_h: "4. Kenarlar",
