                badge_text: "3x3 · BLINDFOLDED",
                hero_title1: "3BLD",
                hero_titleAccent: "Algorithms",
                hero_p: "Blindfolded solving with Old Pochmann: a step-by-step guide, the letter scheme, a letter quiz and setup moves for every letter. All verified by simulation.",
                guide_h: "📘 Guide: blindfolded solving with Old Pochmann",
                g_intro: "In blindfolded solving you first inspect and memorise the cube, then close your eyes and solve it without looking. In Old Pochmann one piece goes home at a time. All you need is two algorithms (T-perm and a modified Y-perm) plus short setup moves.",
                g_hold_h: "1. Orientation",
                g_hold_p: "Hold the cube white on top, green in front and never rotate it during the solve. All letters and moves on this page use this orientation.",
                g_scheme_h: "2. Letter scheme (Speffz)",
                g_scheme_p: "Every sticker gets a letter. On each face you start at the top left and go clockwise; corners and edges each use the letters A–X separately. Face order: up (A–D), left (E–H), front (I–L), right (M–P), back (Q–T), down (U–X).",
                fig_edges: "Edge letters",
                fig_corners: "Corner letters",
                fig_note: "Dark sticker: the buffer. The other stickers of the buffer piece are never targets.",
                g_memo_h: "3. Memorisation (tracing)",
                g_memo_p: "Look at the sticker in the buffer: write down the letter of the spot where that sticker belongs. Then look at the sticker in that spot and continue the same way. If the buffer piece comes back to the buffer (the cycle closes), write the letter of any piece that is not solved yet and continue from there. Pieces that are in place but twisted or flipped are solved the same way with two letters.",
                g_memo_tip: "Tip: turn the letters into words two at a time (e.g. KA → kayak, BE → bed). Edges are easy to remember as words, corners by repeating them as sounds.",
                g_edges_h: "4. Edges",
                g_edges_p: "Buffer B (top sticker of the up-right edge), swap spot D (top sticker of the up-left edge). For each letter: bring the target sticker to D with the setup moves, do the T-perm, undo the setup. The setup moves never disturb the buffer or the corners the T-perm swaps.",
                g_corners_h: "5. Corners",
                g_corners_p: "Buffer A (top sticker of the up-left-back corner), swap spot P (right sticker of the down-front-right corner). For each letter: setup, modified Y-perm, undo the setup.",
                g_parity_h: "6. Parity",
                g_parity_p: "If you have an odd number of edge letters (then the corner letters are odd too), do this algorithm after the edges and before the corners:",
                g_order_h: "7. Order of the solve",
                g_order_p: "Memorise corners and edges → close your eyes → edges → parity if needed → corners. This order and all algorithms were tested by simulation on 300 random scrambles; the cube was solved every time.",
                quiz_h: "🔤 Letter quiz",
                quiz_p: "Pick the letter of the highlighted sticker.",
